function biggestTank(heights: number[]): number {
  let lo = 0, hi = heights.length - 1, best = 0;
  while (lo < hi) {
    const level = Math.min(heights[lo], heights[hi]);
    best = Math.max(best, level * (hi - lo));
    if (heights[lo] < heights[hi]) lo++;
    else hi--;
  }
  return best;
}

